// ИТОГ для пользователя: статус, живой аудит, свод сборщика, доки.
const src = $('Пора завершать?').last().json || {};
const aud = $('Аудитор (ищет баги)').last().json || {};
const coll = $('Сборщик информации (4 канала)').last().json || {};
const doc = $('Документатор (README)').last().json || {};
const cut = (s, n) => String(s || '').slice(0, n);
return [ { json: {
  status: src.plan_done === 'YES' ? 'План выполнен' : 'Лимит кругов исчерпан - нужен человек',
  ring: src.ring || 0,
  ring_history: 'Кругов пройдено: ' + (src.ring || 0),
  audit_summary: cut(aud.output, 3000),
  collector_summary: cut(coll.output, 3000),
  doc: cut(doc.output, 500)
} } ];

// Счётчик полных кругов кольца (лимит 3). Обновлено 08.10: ring живёт в static data —
// агентские ноды (Аудитор/Сборщик) не пробрасывают поля, поэтому $json.ring не доходит.
// run_id: в новом исполнении счёт с нуля (страховка; первым store сбрасывает парсер Аудитора).
const store = $getWorkflowStaticData('global');
if (store.run_id !== $execution.id) { store.run_id = $execution.id; store.ring = 0; }
store.ring = (store.ring || 0) + 1;
const ring = store.ring;
// task: текстовый свод Сборщика передаём Аудитору (его text читает $json.task).
return [ { json: { ...$json, task: String($json.output || $json.task || ''), ring: ring, ring_limit: ring >= 3 ? 'YES' : 'NO', pass: 'RING' } } ];

// Счётчик петель этапа канала «Браузер» (лимит 3). Обновлено 10.10: cycle_n живёт в static data —
// парсеры шагов строят объект заново (Object.assign от base), поэтому $json.cycle_n не доходит.
const store = $getWorkflowStaticData('global');
if (store.cycle_run_id !== $execution.id) { store.cycle_run_id = $execution.id; store.cycle_ch = {}; }
const n = (store.cycle_ch.browser || 0) + 1;
store.cycle_ch.browser = n;
return [ { json: { ...$json, cycle_n: n, cycle_limit: n >= 3 ? 'YES' : 'NO' } } ];

// Счётчик петель этапа канала «API» (лимит 3). Обновлено 10.10: cycle_n живёт в static data —
// парсеры шагов строят объект заново (Object.assign от base), поэтому $json.cycle_n не доходит.
const store = $getWorkflowStaticData('global');
if (store.cycle_run_id !== $execution.id) { store.cycle_run_id = $execution.id; store.cycle_ch = {}; }
const n = (store.cycle_ch.api || 0) + 1;
store.cycle_ch.api = n;
return [ { json: { ...$json, cycle_n: n, cycle_limit: n >= 3 ? 'YES' : 'NO' } } ];

// Счётчик петель этапа канала «Редактор» (лимит 3). Обновлено 10.10: cycle_n живёт в static data —
// парсеры шагов строят объект заново (Object.assign от base), поэтому $json.cycle_n не доходит.
const store = $getWorkflowStaticData('global');
if (store.cycle_run_id !== $execution.id) { store.cycle_run_id = $execution.id; store.cycle_ch = {}; }
const n = (store.cycle_ch.editor || 0) + 1;
store.cycle_ch.editor = n;
return [ { json: { ...$json, cycle_n: n, cycle_limit: n >= 3 ? 'YES' : 'NO' } } ];

// Счётчик петель этапа канала «MCP» (лимит 3). Обновлено 10.10: cycle_n живёт в static data —
// парсеры шагов строят объект заново (Object.assign от base), поэтому $json.cycle_n не доходит.
const store = $getWorkflowStaticData('global');
if (store.cycle_run_id !== $execution.id) { store.cycle_run_id = $execution.id; store.cycle_ch = {}; }
const n = (store.cycle_ch.mcp || 0) + 1;
store.cycle_ch.mcp = n;
return [ { json: { ...$json, cycle_n: n, cycle_limit: n >= 3 ? 'YES' : 'NO' } } ];

// ПАРСЕР вердикта Аудитора (пункт 2): plan_done + метка кольца для нод-шлагбаумов.
// plan_done: ПЕРВОЕ упоминание plan_done=YES|NO внутри секции «ВЕРДИКТ» (fallback — первое вне служебных фраз).
// F11: прежняя версия брала ПОСЛЕДНЕЕ упоминание и ложно вернула YES на тексте с вердиктом NO. Теперь ложный YES невозможен.
// pass/ring/ring_limit: состояние кольца из static data (пишет «Счётчик кругов»).
// run_id: новый запуск => ring=0, auto=false (согласование старта обязательно), user_edits=''.
const store = $getWorkflowStaticData('global');
if (store.run_id !== $execution.id) { store.run_id = $execution.id; store.ring = 0; store.auto = false; store.user_edits = ''; }
const text = String($json.output || '');
const pick = (s) => {
  const m = /plan_done\s*[=:]\s*['"«`]?\s*(YES|NO)/i.exec(s);
  return m ? m[1].toUpperCase() : null;
};
let plan_done = null;
const vh = text.search(/ВЕРДИКТ/i);
if (vh >= 0) plan_done = pick(text.slice(vh, vh + 3000));
if (!plan_done) {
  const ms = [...text.matchAll(/plan_done\s*[=:]\s*['"«`]?\s*(YES|NO)/gi)];
  for (const mm of ms) {
    const pre = text.slice(Math.max(0, mm.index - 60), mm.index).toLowerCase();
    if (/перевод|требует|чтобы|станет|для/.test(pre)) continue;
    plan_done = mm[1].toUpperCase();
    break;
  }
}
if (!plan_done) plan_done = 'NO';
const ring = store.ring || 0;
return [ { json: { ...$json, plan_done: plan_done, ring: ring, ring_limit: ring >= 3 ? 'YES' : 'NO', pass: ring > 0 ? 'RING' : 'FIRST' } } ];

// ПАРСЕР вывода Распределителя (пункт 2): флаги work_* и задачи task_* по каналам.
// Основной путь: ПОСЛЕДНИЙ JSON-блок с work_browser (шаблон формата из промпта может идти раньше — он не берётся).
// Флаг принимается строго 'YES'; всё прочее ('NO', 'YES|NO', '<...>' и т.п.) -> 'NO' + пометка в parse_warn.
// Запасной путь: построчный поиск 'work_x = значение' и 'task_x: ...' (значение YES|NO не считается YES).
// Полный провал: все каналы 'NO' (безопасный простой) + parse_warn в данных.
const text = String($json.output || '');
const flat = text.replace(/[«»'"]/g, '');
const chans = ['browser', 'api', 'editor', 'mcp'];
const flags = {};
const tasks = {};
for (const ch of chans) { flags['work_' + ch] = 'NO'; tasks['task_' + ch] = ''; }
let parse_warn = '';
const strip = v => String(v == null ? '' : v).trim().replace(/^["']+|["']+$/g, '');
const isStub = v => v === '...' || v === '…' || /^yes\s*[|/]\s*no$/i.test(v) || /^<.+>$/.test(v);
const blocks = [...text.matchAll(/\{[^{}]*"work_browser"[^{}]*\}/g)];
let obj = null;
if (blocks.length) {
  try { obj = JSON.parse(blocks[blocks.length - 1][0]); } catch (err) { parse_warn = 'JSON-блок не распознан: ' + err.message; }
}
if (obj) {
  for (const ch of chans) {
    const rawV = strip(obj['work_' + ch]).toUpperCase();
    if (rawV === 'YES') { flags['work_' + ch] = 'YES'; }
    else {
      flags['work_' + ch] = 'NO';
      if (rawV !== '' && rawV !== 'NO') parse_warn += (parse_warn ? '; ' : '') + 'work_' + ch + '="' + rawV + '" трактован как NO';
    }
    let tv = strip(obj['task_' + ch]);
    if (isStub(tv)) tv = '';
    tasks['task_' + ch] = tv;
  }
} else {
  let found = false;
  for (const ch of chans) {
    const wm = flat.match(new RegExp('work_' + ch + '\\s*[=:]\\s*([^\\s,;]+)', 'i'));
    if (wm) {
      found = true;
      const v = wm[1].toUpperCase().replace(/[.,;:!?)\]}»"']+$/g, '');
      if (v === 'YES') { flags['work_' + ch] = 'YES'; }
      else { flags['work_' + ch] = 'NO'; if (v !== 'NO') parse_warn += (parse_warn ? '; ' : '') + 'work_' + ch + '="' + v + '" трактован как NO'; }
    }
    const tm = flat.match(new RegExp('task_' + ch + '\\s*[=:]\\s*(.+)', 'i'));
    if (tm) { let tv = strip(tm[1]); if (isStub(tv)) tv = ''; tasks['task_' + ch] = tv; }
  }
  if (!found && !parse_warn) parse_warn = 'Рабочие флаги work_* в ответе не найдены';
}
for (const ch of chans) { if (flags['work_' + ch] === 'NO') tasks['task_' + ch] = ''; }
return [ { json: { ...$json, ...flags, ...tasks, parse_warn: parse_warn } } ];

// АГРЕГАТОР-СУПЕРВИСОР («ждать всех», фикс ②): ждёт отчёты каналов из шины (каналы — отдельные исполнения).
// Вход: строки шины (или пусто) из «Шина: чтение». Выход ВСЕГДА один элемент с agg_done;
// false — кольцо ещё ждёт (назад на «Шина: ожидание (60с)»), true — идём в Сборщик.
// run_id фильтруем ЗДЕСЬ (в коде), а не фильтром dataTable — так кольцо не зависит от резолва выражения в фильтре.
const store = $getWorkflowStaticData('global');
if (store.bus_run !== $execution.id) { store.bus_run = $execution.id; store.bus_polls = 0; }
store.bus_polls++;
const runId = String($execution.id);
let flags = {};
try { flags = $('Веер: запуск каналов (код)').first().json.flags || {}; } catch (e) {}
const expected = Object.keys(flags).filter(c => flags[c] === 'YES');
const all = $input.all().map(i => i.json).filter(r => r && r.channel && r.channel !== 'none');
const waveStart = Number(store.wave_start_ms || 0);
const rows = all.filter(r => String(r.run_id || '') === runId && (waveStart <= 0 || new Date(String(r.createdAt || '')).getTime() >= waveStart - 2000));
const seen = {};
const parts = [];
for (const r of rows) {
  const ch = String(r.channel);
  if (seen[ch]) continue;
  seen[ch] = r;
  parts.push('--- Канал ' + ch + ' (' + String(r.status || 'done') + ') ---\n' + String(r.summary || '').slice(0, 2000));
}
const missing = expected.filter(c => !seen[c]);
const cap = 75; // 75 опросов × 60 c ≈ 75 минут — жёсткий предел ожидания каналов
const timeout = store.bus_polls >= cap;
const done = missing.length === 0 || timeout;
let task = 'СВОДКА ВЕТОК КАНАЛОВ (' + (expected.length - missing.length) + ' из ' + expected.length + '):\n\n' + (parts.join('\n\n') || 'отчётов нет');
if (!expected.length) task = 'СВОДКА ВЕТОК КАНАЛОВ: задач ни одному каналу не поставлено (все NO).';
if (timeout && missing.length) task += '\n\nВНИМАНИЕ (сторож): каналы не отчитались за ' + cap + ' минут: ' + missing.join(', ') + '. Это пропуск — сверь их исполнения по run_id ' + runId + '.';
return [{ json: { task: task, agg_done: done, agg_missing: missing, agg_run_id: runId, agg_polls: store.bus_polls, agg_expected: expected, agg_seen: Object.keys(seen), agg_rows: rows.length, agg_all_rows: all.length, agg_flags: flags } }];

// Парсер шага 2 «Синтетические тесты».
const text = String($json.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*?"test"[\s\S]*?\}/); if (m) p = JSON.parse(m[0]); } catch (e) { p = {}; }
if (!p || Object.keys(p).length === 0) {
  const nx = (re, d) => { const m = text.match(re); return m ? String(m[1]).trim() : d; };
  p = {
    test: nx(/test\s*[=:]\s*['"«]?([^\n"»]+)/i, 'Тест не распознан'),
    test_path: nx(/test_path\s*[=:]\s*['"«]?([^\n"»]+)/i, 'tests/test_editor.py (позже .gd)')
  };
}
let base = {};
try { base = $('Редактор: 1. Причина (парсер)').last().json; } catch (e) { base = {}; }
return [{ json: Object.assign({}, base, { test: String(p.test || ''), test_path: String(p.test_path || ''), test_red: 'RED', step2_raw: text.slice(0, 1500) }) }];

// Парсер шага 3 «Фикс».
const text = String($json.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*?"fix"[\s\S]*?\}/); if (m) p = JSON.parse(m[0]); } catch (e) { p = {}; }
if (!p || Object.keys(p).length === 0) {
  const m = text.match(/fix\s*[=:]\s*['"«]?([^\n"»]+)/i);
  p = { fix: m ? String(m[1]).trim() : 'Фикс не распознан' };
}
let base = {};
try { base = $('Редактор: 2. Синтетические тесты (парсер)').last().json; } catch (e) { base = {}; }
return [{ json: Object.assign({}, base, { fix: String(p.fix || ''), step3_raw: text.slice(0, 1500) }) }];

// Парсер шага 4 «Прогон тестов»: вердикт GREEN|RED (дефолт RED — безопасно).
const text = String($json.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*?"verdict"[\s\S]*?\}/); if (m) p = JSON.parse(m[0]); } catch (e) { p = {}; }
if (!p || Object.keys(p).length === 0) {
  const nx = (re, d) => { const m = text.match(re); return m ? String(m[1]).trim() : d; };
  p = {
    verdict: (nx(/verdict\s*[=:]\s*['"«]?\s*(GREEN|RED)/i, 'RED') || 'RED').toUpperCase(),
    detail: nx(/detail\s*[=:]\s*['"«]?([^\n"»]*)/i, '')
  };
}
const v = String(p.verdict || 'RED').toUpperCase() === 'GREEN' ? 'GREEN' : 'RED';
let base = {};
try { base = $('Редактор: 3. Фикс (парсер)').last().json; } catch (e) { base = {}; }
return [{ json: Object.assign({}, base, { verdict: v, detail: String(p.detail || ''), step4_raw: text.slice(0, 1500) }) }];

// Парсер шага 5 «Аудит-2»: чистота + куда вернуться + ещё этапы. clean=YES только если audit=CLEAN и тесты GREEN (реализация RED-пути п.5).
const text = String($json.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*?"audit"[\s\S]*?\}/); if (m) p = JSON.parse(m[0]); } catch (e) { p = {}; }
if (!p || Object.keys(p).length === 0) {
  const nx = (re, d) => { const m = text.match(re); return m ? String(m[1]).trim() : d; };
  p = {
    audit: (nx(/audit\s*[=:]\s*['"«]?\s*(CLEAN|ISSUES)/i, 'ISSUES') || 'ISSUES').toUpperCase(),
    return_to: (nx(/return_to\s*[=:]\s*['"«]?\s*(CAUSE|FIX|TESTS)/i, 'CAUSE') || 'CAUSE').toUpperCase(),
    more_stages: (nx(/more_stages\s*[=:]\s*['"«]?\s*(YES|NO)/i, 'NO') || 'NO').toUpperCase(),
    audit_note: nx(/audit_note\s*[=:]\s*['"«]?([^\n"»]*)/i, '')
  };
}
const audit = String(p.audit || 'ISSUES').toUpperCase() === 'CLEAN' ? 'CLEAN' : 'ISSUES';
const rtRaw = String(p.return_to || '').toUpperCase();
const rt = ['CAUSE', 'FIX', 'TESTS'].indexOf(rtRaw) >= 0 ? rtRaw : 'CAUSE';
const ms = String(p.more_stages || 'NO').toUpperCase() === 'YES' ? 'YES' : 'NO';
let base = {};
try { base = $('Редактор: 4. Прогон тестов (парсер)').last().json; } catch (e) { base = {}; }
const verdict = String(base.verdict || 'RED').toUpperCase();
const clean = (audit === 'CLEAN' && verdict !== 'RED') ? 'YES' : 'NO';
return [{ json: Object.assign({}, base, { audit: audit, audit_note: String(p.audit_note || ''), return_to: rt, more_stages: ms, clean: clean, step5_raw: text.slice(0, 1500) }) }];

// Парсер шага 1 «Причина»: разбирает ответ модели, сливает с артефактами канала и кольца.
const text = String($json.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*?"nothing_to_do"[\s\S]*?\}/); if (m) p = JSON.parse(m[0]); } catch (e) { p = {}; }
if (!p || Object.keys(p).length === 0) {
  const nx = (re, d) => { const m = text.match(re); return m ? String(m[1]).trim() : d; };
  p = {
    nothing_to_do: (nx(/nothing_to_do\s*[=:]\s*['"«]?\s*(YES|NO)/i, 'NO') || 'NO').toUpperCase(),
    hypothesis: nx(/hypothesis\s*[=:]\s*['"«]?([^\n"»]+)/i, 'Гипотеза не распознана')
  };
}
const nd = String(p.nothing_to_do || 'NO').toUpperCase() === 'YES' ? 'YES' : 'NO';
let base = {};
try { base = $('Редактор: Куда вернуться?').isExecuted ? $('Редактор: Куда вернуться?').last().json : $('Редактор: Есть работа?').last().json; } catch (e) { base = {}; }
const attempt = (Number(base.attempt) || 0) + 1;
const lim = attempt >= 4 ? 'YES' : 'NO';
let channelOutput = '';
try { channelOutput = String($('Канал: Редактор').last().json.output || '').slice(0, 1500); } catch (e) { channelOutput = ''; }
return [{ json: Object.assign({}, base, { hypothesis: String(p.hypothesis || ''), nothing_to_do: nd, attempt: attempt, attempt_limit: lim, step1_raw: text.slice(0, 1500), channel_output: channelOutput }) }];

// «Аудитор: промпт (память)»: история сессии (Data Table) + текущая задача.
const rows = $input.all().map(i => i.json).filter(r => r && r.content !== undefined && r.content !== '');
rows.reverse();
const hist = rows.map(r => String(r.role || 'user') + ': ' + String(r.content || '')).join('\n').slice(0, 3000);
const sessionKey = $('Чат (общий вход)').isExecuted ? 'core-' + $('Чат (общий вход)').first().json.sessionId : 'core';
let task = '';
const cands = ['Счётчик кругов (лимит 3)', 'Испытатель (adversarial)', 'Вход: MCP (webhook)', 'Вход: Редактор (webhook)', 'Вход: API (webhook)', 'Вход: Браузер (webhook)', 'Чат (общий вход)', 'Вход: Ручной запуск'];
for (const n of cands) {
  try {
    const j = $(n).first().json;
    let t = j.task || j.chatInput || (j.body && (j.body.task || j.body.text || j.body.chatInput)) || '';
    if (!t && n === 'Испытатель (adversarial)') t = j.output || '';
    if (t && String(t).trim()) { task = String(t); break; }
  } catch (e) {}
}
if (!task) task = 'Проверь статус проекта и реши, выполнен ли план';
const prompt = (hist ? '[ИСТОРИЯ СЕССИИ ' + sessionKey + ']\n' + hist + '\n[КОНЕЦ ИСТОРИИ]\n\n' : '') + task;
return [{ json: { task: prompt, task_input: task, session_key: sessionKey, mem_rows: rows.length } }];

// «Аудитор: подготовка записи (память)»: user-задача + assistant-ответ.
const answer = String(($json.output !== undefined ? $json.output : ($json.text || '')) || '').slice(0, 4000);
let taskInput = '', sessionKey = '';
try { const m = $('Аудитор: промпт (память)').last().json; taskInput = String(m.task_input || ''); sessionKey = String(m.session_key || ''); } catch (e) {}
if (!sessionKey) sessionKey = $('Чат (общий вход)').isExecuted ? 'core-' + $('Чат (общий вход)').first().json.sessionId : 'core';
const out = [];
if (taskInput) out.push({ json: { session: sessionKey, role: 'user', content: taskInput.slice(0, 4000) } });
if (answer) out.push({ json: { session: sessionKey, role: 'assistant', content: answer } });
return out;

// «Планировщик: промпт (память)»: история сессии + вывод Аудитора + правки пользователя (REVISE из Cline).
const rows = $input.all().map(i => i.json).filter(r => r && r.content !== undefined && r.content !== '');
rows.reverse();
const hist = rows.map(r => String(r.role || 'user') + ': ' + String(r.content || '')).join('\n').slice(0, 3000);
const sessionKey = $('Чат (общий вход)').isExecuted ? 'core-' + $('Чат (общий вход)').first().json.sessionId : 'core';
let task = '';
try { task = String($('Аудитор (ищет баги)').last().json.output || ''); } catch (e) { task = ''; }
if (!task) task = 'Составь план исправлений';
// Правки пользователя (одноразовая добавка к промпту, ставит «Решение: парсер (Cline)»).
const store = $getWorkflowStaticData('global');
let edits = String(store.user_edits || '');
if (edits) { store.user_edits = ''; }
const tail = edits ? ('\n\n[ПРАВКИ ПОЛЬЗОВАТЕЛЯ К ПЛАНУ]\n' + edits + '\n[КОНЕЦ ПРАВОК]') : '';
const prompt = (hist ? '[ИСТОРИЯ СЕССИИ ' + sessionKey + ']\n' + hist + '\n[КОНЕЦ ИСТОРИИ]\n\n' : '') + task + tail;
return [{ json: { task: prompt, task_input: task, session_key: sessionKey, mem_rows: rows.length } }];

// «Планировщик: подготовка записи (память)»: user-задача + assistant-план.
const answer = String(($json.output !== undefined ? $json.output : ($json.text || '')) || '').slice(0, 4000);
let taskInput = '', sessionKey = '';
try { const m = $('Планировщик: промпт (память)').last().json; taskInput = String(m.task_input || ''); sessionKey = String(m.session_key || ''); } catch (e) {}
if (!sessionKey) sessionKey = $('Чат (общий вход)').isExecuted ? 'core-' + $('Чат (общий вход)').first().json.sessionId : 'core';
const out = [];
if (taskInput) out.push({ json: { session: sessionKey, role: 'user', content: taskInput.slice(0, 4000) } });
if (answer) out.push({ json: { session: sessionKey, role: 'assistant', content: answer } });
return out;

