// Решение пользователя из resume-вебхука Wait (Cline -> n8n).
// body: { decision: 'APPROVE'|'REVISE'|'STOP', user_edits: string, auto: bool }.
// STOP/СТОП/CANCEL/ОТМЕНА/ХВАТИТ: остановка без пересборки плана — строка PLAN закрывается
// статусом STOP, финальный отчёт пишет ветка «Стоп? (STOP)». Регистр и язык слова-стопа не важны.
const body = $json.body || $json;
const s = (v) => String(v == null ? '' : v).trim();
const raw = s(body.decision).toUpperCase();
const stopWords = ['STOP', 'СТОП', 'CANCEL', 'ОТМЕНА', 'ОТМЕНИТЬ', 'ХВАТИТ'];
const isStop = stopWords.includes(raw);
const decision = isStop ? 'STOP' : (raw === 'APPROVE' ? 'APPROVE' : 'REVISE');
const edits = s(body.user_edits || body.edits).slice(0, 4000);
const autoRaw = body.auto;
const auto = autoRaw === true || String(autoRaw).toLowerCase() === 'true' || String(autoRaw) === '1';
let plan = '', ring = 0;
try { const p = $('Отчёт: пакет (аудит+план)').last().json; plan = String(p.plan || ''); ring = Number(p.ring || 0); } catch (e) {}
const store = $getWorkflowStaticData('global');
store.auto = decision === 'APPROVE' ? auto : false;
store.user_edits = decision === 'REVISE' ? edits : '';
return [{ json: {
  decision: decision,
  status_norm: decision === 'APPROVE' ? 'APPROVED' : (decision === 'STOP' ? 'STOP' : 'REVISE'),
  user_edits: edits || (decision === 'STOP' ? 'Остановлено из чата Cline (STOP)' : ''),
  auto: store.auto,
  ring: ring,
  output: plan,
  plan: plan
} }];

