// Выход: до 4 элементов {url, body, flags, run_id} или один {no_run:true} — тогда запусков нет.
const p = $json; // выход «Распределитель: парсер флагов»
const session = $('Чат (общий вход)').isExecuted ? String($('Чат (общий вход)').first().json.sessionId || '') : '';
const runId = String($execution.id);
const base = 'http://localhost:5678/webhook/';
// Шаг 0 (изоляция v3): канальные вебхуки с префиксом v3-, чтобы v3 не топтал живой v2.
const defs = [
  ['browser', 'work_browser', 'task_browser', 'v3-ch-browser'],
  ['api', 'work_api', 'task_api', 'v3-ch-api'],
  ['editor', 'work_editor', 'task_editor', 'v3-ch-editor'],
  ['mcp', 'work_mcp', 'task_mcp', 'v3-ch-mcp']
];
// Шаг 1 (событийная шина): канал получит этот resume-URL и разбудит wait вебхуком после отчёта.
let resumeUrl = '';
try { resumeUrl = String($execution.resumeUrl || ''); } catch (e) {}
const flags = {};
const out = [];
for (const d of defs) {
  const ch = d[0];
  const task = String((p && p[d[2]]) || '').trim();
  const ok = String((p && p[d[1]]) || '') === 'YES' && task !== '';
  flags[ch] = ok ? 'YES' : 'NO';
  if (ok) out.push({ json: { channel: ch, url: base + d[3], flags: flags, run_id: runId, body: { session: session, task: task, run_id: runId, ring: Number((p && p.ring) || 0), bus_resume: resumeUrl } } });
}
if (!out.length) return [{ json: { no_run: true, channel: 'none', flags: flags, run_id: runId } }];
return out;

