const rows = $input.all().map(i => i.json).filter(r => r && r.content !== undefined && r.content !== '');
rows.reverse();
const hist = rows.map(r => String(r.role || 'user') + ': ' + String(r.content || '')).join('\n').slice(0, 3000);
let sessionKey = '';
try { sessionKey = String($('MCP: Есть работа?').last().json.session_key || '').replace(/^channel-mcp-/, 'planner-mcp-'); } catch (e) {}
if (!sessionKey) sessionKey = $('Чат (общий вход)').isExecuted ? 'planner-mcp-' + $('Чат (общий вход)').first().json.sessionId : 'planner-mcp';
let task = '';
try { task = String($('MCP: Есть работа?').last().json.task_mcp || ''); } catch (e) { task = ''; }
if (!task) task = 'Спланируй задачу канала MCP';
const prompt = (hist ? '[ИСТОРИЯ СЕССИИ ' + sessionKey + ']\n' + hist + '\n[КОНЕЦ ИСТОРИИ]\n\n' : '') + task;
return [{ json: { task: prompt, task_input: task, session_key: sessionKey, mem_rows: rows.length } }];

// «Планировщик MCP: подготовка записи (память)»: user-задача канала + assistant-задание.
const answer = String(($json.output !== undefined ? $json.output : ($json.text || '')) || '').slice(0, 4000);
let taskInput = '', sessionKey = '';
try { const m = $('Планировщик MCP: промпт (память)').last().json; taskInput = String(m.task_input || ''); sessionKey = String(m.session_key || ''); } catch (e) {}
if (!sessionKey) sessionKey = $('Чат (общий вход)').isExecuted ? 'planner-mcp-' + $('Чат (общий вход)').first().json.sessionId : 'planner-mcp';
const out = [];
if (taskInput) out.push({ json: { session: sessionKey, role: 'user', content: taskInput.slice(0, 4000) } });
if (answer) out.push({ json: { session: sessionKey, role: 'assistant', content: answer } });
return out;

// «Браузер: дзынь шине (код)»: будим ядро — wait шины резюмится вебхуком сразу после отчёта канала.
const store = $getWorkflowStaticData('global');
const url = String(store.bus_resume || '');
if (!url) return [];
return [{ json: { bus_resume: url, signal_channel: 'browser' } }];

